INSERT [dbo].[chat_Info] ([c_ID], [c_Class], [c_Conts], [c_Date], [c_Title], [U_ID]) VALUES (1, N'英文', N'想問一下版上的大家~如書上寫的這樣 可是我網路上找子母音總表是可以結合的！請問哪個是對的啊', '2021-7-20 4:15:34PM', N'母音子音結合', 'tajenwww')
INSERT [dbo].[chat_Info] ([c_ID], [c_Class], [c_Conts], [c_Date], [c_Title], [U_ID]) VALUES (2, N'法文', N'想請問有沒有推薦程度比較低的法文影片，就是速度比較沒那麼快然後適合法國小朋友學習法文聽力的？
